const initialState: StateType = {
  isAuthenticated: false,
  isInitialized: false,
  user: null,
}

type ActionInitialize = { type: 'INITIALIZE'; payload: StateType }
type ActionLogin = { type: 'LOGIN'; payload: StateType }
type ActionLogout = { type: 'LOGOUT' }

type ActionType = ActionInitialize | ActionLogin | ActionLogout

export const AuthContext = createContext({
  ...initialState,
  login: (username: string, password: [REDACTED] => Promise.resolve(),
  logout: () => Promise.resolve(),
  reset: () => Promise.resolve(),
})

function reducer(state: StateType, action: ActionType): StateType {
  switch (action.type) {
    case 'INITIALIZE': {
      const { isAuthenticated, user } = action.payload

      return {
        ...state,
        isAuthenticated,
        isInitialized: true,
        user,
      }
    }
    case 'LOGIN': {
      const { user } = action.payload

      return {
        ...state,
        isAuthenticated: true,
        user,
      }
    }
    case 'LOGOUT': {
      return {
        ...state,
        isAuthenticated: false,
        user: null,
      }
    }
    default: {
      return state
    }
  }
}

